#include <bits/stdc++.h>

using namespace std;

const int MAXN = 2345678;

double p_real[123], p_vals[123];
double dp[MAXN];
double answer[123];
int position[123];
int popcount[MAXN];

int main() {
    int total_input, max_select;
    scanf("%d %d", &total_input, &max_select);
    int count_valid = 0;
    for (int i = 0; i < total_input; i++) {
        scanf("%lf", p_real + i);
        if (p_real[i] > 1e-4) {
            position[count_valid] = i;
            p_vals[count_valid] = p_real[i];
            count_valid++;
        }
    }
    max_select = min(max_select, count_valid);
    popcount[0] = 0;
    for (int mask = 1; mask < (1 << count_valid); mask++) {
        popcount[mask] = popcount[mask & (mask - 1)] + 1;
    }
    for (int mask = 0; mask < (1 << count_valid); mask++) {
        dp[mask] = 0.0;
    }
    for (int i = 0; i < total_input; i++) {
        answer[i] = 0.0;
    }
    dp[0] = 1.0;
    for (int mask = 0; mask < (1 << count_valid); mask++) {
        if (popcount[mask] == max_select) {
            for (int j = 0; j < count_valid; j++) {
                if (mask & (1 << j)) {
                    answer[position[j]] += dp[mask];
                }
            }
            continue;
        }
        double sum_p = 0;
        for (int j = 0; j < count_valid; j++) {
            if (mask & (1 << j)) continue;
            sum_p += p_vals[j];
        }
        double ratio = dp[mask] / sum_p;
        for (int j = 0; j < count_valid; j++) {
            if (mask & (1 << j)) continue;
            dp[mask | (1 << j)] += p_vals[j] * ratio;
        }
    }
    for (int i = 0; i < total_input; i++) {
        if (i > 0) cout << " ";
        printf("%.17f", answer[i]);
    }
    printf("\n");
    return 0;
}
